// 事件输入使用目标消息体，不假定 HTTP 请求或统一消息信封。
import type { EventCtx } from 'fh2-plugin-sdk/backend'

export function onExampleCreated (input: { event_id: string }, ctx: EventCtx): { accepted: boolean } {
  if (!input.event_id || !ctx.idempotencyKey) throw { code: 'INVALID_ARGUMENT', message: '缺少事件业务键' }
  return { accepted: true }
}

export function echo(input: { value: string }, _ctx: HandlerCtx): { value: string } {
  return { value: input.value }
}

import type { WorkflowCtx } from 'fh2-plugin-sdk/backend'

export function handle(_input: { idempotencyKey: string }, ctx: WorkflowCtx): { accepted: boolean } {
  if (!ctx.idempotencyKey) throw { code: 'INVALID_ARGUMENT', message: '缺少幂等键' }
  return { accepted: true }
}

